export const getBulkAddReposUrl = () => {
  return `/repos/bulk`;
};

/**
 * @summary Bulk add repositories
 */
export const bulkAddRepos = async (
  bulkAddReposRequest: NonReadonly<BulkAddReposRequest>,
  options?: Parameters<typeof orvalFetch>[1],
): Promise<SettingsResponse> => {
  const getHeaders = (h?: NonNullable<RequestInit["headers"]>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  return orvalFetch<SettingsResponse>(getBulkAddReposUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(bulkAddReposRequest),
  });
};

